const mongoose = require('mongoose');

const YES_NO = ['yes', 'no', ''];

// Only names generated by the upload route are accepted (prevents path tricks).
const fileSchema = new mongoose.Schema(
  {
    fileName: { type: String, match: /^[0-9a-f-]{36}\.(pdf|jpg|png|webp)$/ },
    originalName: { type: String, default: '' },
    mimeType: { type: String, default: '' },
    size: { type: Number, default: 0 },
  },
  { _id: false }
);

const MAX_FILES = 10;
const filesField = {
  type: [fileSchema],
  default: [],
  validate: [(v) => v.length <= MAX_FILES, `એક વિભાગમાં વધુમાં વધુ ${MAX_FILES} ફાઇલ`],
};

const propertySchema =new mongoose.Schema(
  {
    serialNo: { type: Number, index: true },            // ક્રમ
    propertyId: { type: String, trim: true, default: '' }, // આઈડી
    comesUnder: { type: String, trim: true, default: '' }, // અંતર્ગત (કયા મંદિર હેઠળ)
    village: { type: String, trim: true, default: '' },   // ગામનું નામ
    taluka: { type: String, trim: true, default: '' },    // તાલુકો
    district: { type: String, trim: true, default: '' },  // જીલ્લો
    surveyDetails: { type: String, trim: true, default: '' }, // સર્વે/બ્લોક નંબરની વિગત
    deedNo: { type: String, trim: true, default: '' },    // દ.નં.
    deedDate: { type: Date, default: null },              // તારીખ
    deedFiles: filesField,
    giverNameAddress: { type: String, trim: true, default: '' }, // આપનારનું નામ અને સરનામું
    areaSqm: { type: Number, default: null },             // મિલકતનું ક્ષેત્રફળ (ચો.મી.)
    in712: { type: String, enum: YES_NO, default: '' },   // ૭/૧૨ નામ હા/ના
    propertyCard: { type: String, trim: true, default: '' }, // પ્રોપર્ટી કાર્ડ
    propertyCardFiles: filesField,
    assessment: { type: String, trim: true, default: '' },   // આકારણી
    assessmentFiles: filesField,
    villageForm2: { type: String, trim: true, default: '' }, // ગામ નં. ૨
    purpose: { type: String, trim: true, default: '' },   // વપરાશનો હેતુ
    isNA: { type: String, enum: YES_NO, default: '' },    // એન.એ. થયેલ છે? હા/ના
    naAreaSqm: { type: Number, default: null },           // એન.એ. જમીનનું ક્ષેત્રફળ
    remarks: { type: String, trim: true, default: '' },   // રીમાર્કસ
  },
  { timestamps: true }
);

propertySchema.index({
  propertyId: 'text',
  village: 'text',
  taluka: 'text',
  district: 'text',
  surveyDetails: 'text',
  deedNo: 'text',
  giverNameAddress: 'text',
  remarks: 'text',
});

propertySchema.pre('save', async function assignSerial() {
  if (this.serialNo != null) return;
  const last = await this.constructor.findOne({}, { serialNo: 1 }).sort({ serialNo: -1 }).lean();
  this.serialNo = (last?.serialNo || 0) + 1;
});

module.exports = mongoose.model('Property', propertySchema);
